<script setup lang="ts">
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { ElMessage } from 'element-plus'
import type { Api } from './api'
import { errorName } from './labels'
interface Fact {id:string;category:string;content:string;source_type:string;source_version:number;source_task_id?:string;locator?:string;quote?:string}
interface Check {condition:string;status:string;reason?:string;evidence:Fact[]}
interface Entry {id:string;talent_id:string;state:string;group:string;error_code:string|null;profile_stale:boolean;snapshot:{name:string;kind:string;version:number;facts:Fact[]};result:{score:number|null;checks:Check[];preferred:Check[];explanation:string;dense_score?:number;semantic_rrf?:number;lexical_score?:number;components?:Record<string,[number,number]>}|null}
interface Run {id:string;state:string;outcome:string|null;run_version:number;requirement_version:number;requirement_stale:boolean;rules_stale?:boolean;requirement_status:string;created_at:number;total:number;counts:Record<string,number>;retryable:boolean;rules:Record<string,unknown>;requirement_snapshot:Record<string,unknown>;scope_snapshot:Record<string,unknown>;attempts:{run_version:number;state:string}[];error_code:string|null}
const props=defineProps<{api:Api;requirementId:string;version:number;activeVersion:number|null;status:string;canRun:boolean;canAssociate:boolean}>()
const emit=defineEmits<{open:[id:string];task:[id:string]}>()
const busy=ref(false),runs=ref<Run[]>([]),historyPage=ref(1),historyTotal=ref(0),selected=ref<Run|null>(null),entries=ref<Entry[]>([]),page=ref(1),total=ref(0),group=ref(''),focused=ref<Entry|null>(null)
const includeInternal=ref(false),skill=ref(''),weights=ref({evidence_weight:50,preferred_weight:20,semantic_weight:30}),key=ref(crypto.randomUUID())
let generation=0,polling=false
const names:Record<string,string>={queued:'待处理',running:'处理中',succeeded:'已完成',failed:'失败',pending:'待处理',evaluated:'已评估',pass:'满足',unknown:'待核对',fail:'不满足',complete:'全部处理完成',partial:'部分失败',expired:'租约过期'}
async function run(fn:()=>Promise<void>) {busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function loadHistory(){const data=await props.api<{items:Run[];total:number}>(`/requirements/${props.requirementId}/matches?offset=${(historyPage.value-1)*20}&limit=20`);runs.value=data.items;historyTotal.value=data.total}
async function loadResults(){if(!selected.value)return;const token=generation,id=selected.value.id;const data=await props.api<{items:Entry[];total:number}>(`/matches/${id}/results?offset=${(page.value-1)*20}&limit=20&group=${group.value}`);if(token!==generation)return;entries.value=data.items;total.value=data.total;if(focused.value)focused.value=data.items.find(e=>e.id===focused.value!.id)||null}
async function open(item:Run){generation++;selected.value=item;entries.value=[];total.value=0;page.value=1;group.value='';focused.value=null;await refresh()}
async function refresh(){if(!selected.value)return;const id=selected.value.id,token=generation;try{const item=await props.api<Run>(`/matches/${id}`);if(token!==generation)return;selected.value=item;await loadResults()}catch(error){if(token===generation){selected.value=null;entries.value=[];focused.value=null}throw error}}
async function start(){await run(async()=>{const item=await props.api<Run>(`/requirements/${props.requirementId}/matches`,'POST',{version:props.version,include_internal:includeInternal.value,skill:skill.value,rules:weights.value},key.value);key.value=crypto.randomUUID();await loadHistory();await open(item)})}
async function retry(){await run(async()=>{const item=await props.api<Run>(`/matches/${selected.value!.id}/retry`,'POST',{version:selected.value!.run_version});await open(item)})}
async function associate(entry:Entry,linked:boolean){await run(async()=>{await props.api(`/requirements/${props.requirementId}/talents/${entry.talent_id}`,'PUT',{talent_version:entry.snapshot.version,linked});ElMessage.success(linked?'已标记应聘关系；匹配范围不因此改变':'已取消应聘关系')})}
function resetKey(){key.value=crypto.randomUUID()}
const timer=setInterval(()=>{if(!polling&&selected.value&&['queued','running'].includes(selected.value.state)){polling=true;void refresh().catch(e=>{selected.value=null;entries.value=[];focused.value=null;ElMessage.error((e as Error).message)}).finally(()=>{polling=false})}},2500)
onMounted(()=>void run(loadHistory))
onBeforeUnmount(()=>{generation++;clearInterval(timer)})
</script>
<template>
  <el-card class="matches" data-testid="match-workspace"><h3>全范围人才匹配</h3><p class="muted">使用已生效版本 {{activeVersion??'无'}}；未生效草稿不参与。范围是当前人才查看与任务执行权限的交集，默认全部外部人才，不要求已关联应聘需求。</p>
    <el-form inline :disabled="busy||!canRun" @change="resetKey"><el-checkbox v-model="includeInternal">包含内部员工（排除目标部门现任）</el-checkbox><el-input v-model="skill" placeholder="额外筛选：技能原文包含" style="width:230px" @input="resetKey"/><el-form-item label="证据覆盖权重"><el-input-number v-model="weights.evidence_weight" :min="0" :max="99"/></el-form-item><el-form-item label="加分项权重"><el-input-number v-model="weights.preferred_weight" :min="0" :max="99"/></el-form-item><el-form-item label="语义权重"><el-input-number v-model="weights.semantic_weight" :min="1" :max="100"/></el-form-item></el-form>
    <p class="muted">证据覆盖、加分项与语义相关性权重合计100，无对应条件的项不参与并重新归一。分数用于本次范围内辅助排序，不代表能力、录用概率或不同批次可直接比较的绝对值。</p>
    <el-button v-if="canRun" type="primary" :loading="busy" :disabled="status!=='active'" @click="start">发起新的全范围匹配</el-button><el-button :disabled="busy" @click="run(loadHistory)">刷新历史</el-button>
    <el-table :data="runs" @row-click="(item:Run)=>run(()=>open(item))" data-testid="match-history"><el-table-column label="生成时间"><template #default="s">{{new Date(s.row.created_at*1000).toLocaleString()}}</template></el-table-column><el-table-column prop="requirement_version" label="需求版本"/><el-table-column label="状态"><template #default="s">{{names[s.row.state]||s.row.state}} · {{names[s.row.outcome]||s.row.outcome}}</template></el-table-column><el-table-column prop="total" label="当前可见人数"/></el-table>
    <el-pagination v-model:current-page="historyPage" :total="historyTotal" :page-size="20" layout="prev,pager,next" @current-change="()=>run(loadHistory)"/>
    <section v-if="selected" data-testid="match-detail"><h4>本次结果 · 需求版本 {{selected.requirement_version}} · {{names[selected.state]}} / {{names[selected.outcome||'']}}</h4><el-alert v-if="selected.requirement_stale||selected.requirement_status!=='active'" type="warning" :closable="false" title="需求已有新有效版本或已停用，本次结果仅供历史参考"/>
      <el-alert v-if="selected.rules_stale" type="warning" :closable="false" title="这是已失效规则生成的历史结果，请发起新匹配；不要将旧分组和分数当成当前结论"/><p>当前授权可见 {{selected.total}} 人：已评估 {{selected.counts.evaluated}}、失败 {{selected.counts.failed}}、待处理 {{selected.counts.pending}}。范围在启动时固定，后续新增人才不加入。</p><p v-if="selected.error_code">{{errorName[selected.error_code]||selected.error_code}}</p><el-button @click="run(refresh)">刷新结果</el-button><el-button v-if="canRun&&selected.retryable" @click="retry">重试可恢复失败（保留原快照）</el-button>
      <el-select v-model="group" style="width:200px" @change="page=1;run(loadResults)"><el-option label="全部分组（满足优先）" value=""/><el-option v-for="g in ['pass','unknown','fail','failed','pending']" :key="g" :label="names[g]" :value="g"/></el-select>
      <el-table :data="entries" @row-click="(item:Entry)=>focused=item" data-testid="match-results"><el-table-column label="人才"><template #default="s">{{s.row.snapshot.name}} · {{s.row.snapshot.kind==='internal'?'内部':'外部'}}</template></el-table-column><el-table-column label="硬条件 / 执行"><template #default="s">{{names[s.row.group]||names[s.row.state]}}<small v-if="s.row.error_code"> · {{errorName[s.row.error_code]||s.row.error_code}}</small></template></el-table-column><el-table-column label="匹配分"><template #default="s">{{s.row.state==='evaluated'?(s.row.result?.score??'待最终排序'):'未生成'}}<el-tag v-if="s.row.profile_stale" type="warning">档案已更新</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button @click.stop="emit('open',s.row.talent_id)">打开画像</el-button><el-button v-if="canAssociate" @click.stop="associate(s.row,true)">标记应聘</el-button><el-button v-if="canAssociate" @click.stop="associate(s.row,false)">取消应聘</el-button></template></el-table-column></el-table>
      <el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="()=>run(loadResults)"/>
      <el-card v-if="focused" data-testid="match-evidence"><h4>{{focused.snapshot.name}} · 档案快照版本 {{focused.snapshot.version}}</h4><p v-if="focused.profile_stale">当前档案已更新；下列内容是匹配时快照。</p><p>{{focused.result?.explanation}}</p><p v-if="focused.error_code">执行失败：{{errorName[focused.error_code]||focused.error_code}}，不冒充完整匹配分。</p><div v-for="check in [...(focused.result?.checks||[]),...(focused.result?.preferred||[])]" :key="check.condition"><strong>{{check.condition}}：{{names[check.status]}}</strong><p>{{check.reason}}</p><blockquote v-for="fact in check.evidence" :key="fact.id">{{fact.content}}<small> · 档案事实 {{fact.id}} / {{fact.source_type}} / 来源版本{{fact.source_version}}</small><p v-if="fact.quote">原文：{{fact.quote}} · {{fact.locator}}</p><el-button v-if="fact.source_task_id" @click="emit('task',fact.source_task_id)">查看解析出处</el-button></blockquote><p v-if="!check.evidence.length" class="muted">没有可核对依据</p></div><p>稠密相关性 {{focused.result?.dense_score??'未生成'}} · BM25 {{focused.result?.lexical_score??'未生成'}} · RRF {{focused.result?.semantic_rrf??'未完成排序'}}</p><el-collapse><el-collapse-item title="本次规则、范围及需求快照"><pre>{{JSON.stringify({rules:selected.rules,scope:selected.scope_snapshot,requirement:selected.requirement_snapshot,attempts:selected.attempts},null,2)}}</pre></el-collapse-item><el-collapse-item title="完整档案事实快照"><pre>{{JSON.stringify(focused.snapshot,null,2)}}</pre></el-collapse-item></el-collapse></el-card>
    </section>
  </el-card>
</template>
<style scoped>.matches{margin-top:20px} .el-form{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px} blockquote{margin:8px 0;padding:8px 12px;background:#f1f6f4;white-space:pre-wrap} pre{white-space:pre-wrap;overflow-wrap:anywhere} .el-table{margin-top:12px}</style>
